import os

class Solution:
    def __init__(self):
        self.env_vars = {}
        self._load_env()

    def _load_env(self):
        """From .env read key (LaunchAgent environment may not have)."""
        try:
            with open('.env', 'r') as f:
                for line in f:
                    if line.strip() and not line.startswith('#'):
                        key, value = line.split('=', 1)
                        self.env_vars[key] = value
        except FileNotFoundError:
            pass

    def get_env_var(self, key):
        return self.env_vars.get(key)

def test__load_env():
    solution = Solution()
    assert solution.get_env_var("TEST_KEY") is None
