    def build_playlist_subtitle(self, owner: str, privacy: str, year: int | str | None, track_count: int) -> str:
        """Build the metadata subtitle line for a playlist header."""
        # Format: "Owner · Privacy · Year · N tracks"
        # Privacy and year are omitted when empty/None.
        result = []
        if owner:
            result.append(owner)
        if privacy:
            result.append(privacy)
        if year is not None:
            result.append(str(year))
        result.append(f"{track_count} tracks")
        return " · ".join(result)

def test_build_playlist_subtitle():
    solution = Solution()
    assert solution.build_playlist_subtitle("Dana", "Shared", 2020, 24) == "Dana · Shared · 2020 · 24 tracks"
```

